local sources, paths = {}, {}
local manifest = [=[engine	engine	9933
flimg	flimg	19681
core.ai	core/ai	5127
core.audio	core/audio	2551
core.buffer	core/buffer	21016
core.camera	core/camera	4432
core.color	core/color	5177
core.console	core/console	4359
core.db	core/db	3671
core.debug	core/debug	170
core.ecs	core/ecs	4390
core.error	core/error	1695
core.event	core/event	738
core.input	core/input	4340
core.input_mapper	core/input_mapper	548
core.loader	core/loader	4064
core.logger	core/logger	800
core.math	core/math	2966
core.network	core/network	9390
core.particles	core/particles	3757
core.pathfinding	core/pathfinding	3641
core.physics	core/physics	2859
core.scene	core/scene	18459
core.serialization	core/serialization	2850
core.server	core/server	13667
core.storage	core/storage	1033
